 5→use Illuminate\Http\Request;
 6→use Illuminate\Support\Facades\File;
 7→use Inertia\Middleware;
 8→
 9→class HandleInertiaRequests extends Middleware
10→{
11→    /**
12→     * The root template that's loaded on the first page visit.
13→     *
14→     * @see https://inertiajs.com/server-side-setup#root-template
15→     *
16→     * @var string
17→     */
18→    protected $rootView = 'app';
19→
20→    /**
21→     * Determines the current asset version.
22→     *
23→     * @see https://inertiajs.com/asset-versioning
24→     */
25→    public function version(Request $request): ?string
26→    {
27→        return parent::version($request);
28→    }
29→
30→    /**
31→     * Define the props that are shared by default.
32→     *
33→     * @see https://inertiajs.com/shared-data
34→     *
35→     * @return array<string, mixed>
36→     */
37→    public function share(Request $request): array
38→    {
39→        return [
40→            ...parent::share($request),
41→            'name' => config('app.name'),
42→            'auth' => [
43→                'user' => $request->user(),
44→            ],
45→            'sidebarOpen' => ! $request->hasCookie('sidebar_state') || $request->cookie('sidebar_state') === 'true',
46→            'locale' => app()->getLocale(),
47→            'translations' => fn () => $this->getTranslations(),
48→        ];
49→    }
50→
51→    /**
52→     * @return array<string, string>
53→     */
54→    private function getTranslations(): array
55→    {
56→        $locale = app()->getLocale();
57→        $path = lang_path("{$locale}.json");
58→
59→        if (File::exists($path)) {
60→            return json_decode(File::get($path), true) ?? [];
61→        }
62→
63→        return [];
64→    }
65→}
