145→type Filter = 'all' | 'pending' | 'resolved';
146→
147→export default function NormativaIndex({ regulations }: Props) {
148→    const [filter, setFilter] = useState<Filter>('all');
149→
150→    const filtered = regulations.filter((r) => {
151→        if (filter === 'pending') return !r.is_resolved;
152→        if (filter === 'resolved') return r.is_resolved;
153→        return true;
154→    });
155→
156→    const urgentCount = regulations.filter((r) => r.severity === 'urgent' && !r.is_resolved).length;
157→    const warningCount = regulations.filter((r) => r.severity === 'warning' && !r.is_resolved).length;
158→    const infoCount = regulations.filter((r) => r.severity === 'info' && !r.is_resolved).length;
159→
160→    const filters: { key: Filter; label: string }[] = [
161→        { key: 'all', label: 'Todas' },
162→        { key: 'pending', label: 'Pendientes' },
163→        { key: 'resolved', label: 'Resueltas' },
164→    ];
165→
166→    return (
167→        <AppLayout breadcrumbs={breadcrumbs}>
168→            <Head title="Normativa" />
169→            <div className="flex flex-col gap-5 p-6">
170→                <h1 className="text-2xl font-bold">Mis Alertas y Normativa</h1>
171→
172→                <div className="flex items-center gap-3">
173→                    {urgentCount > 0 && (
174→                        <span className="inline-flex items-center gap-1 bg-[#E53935] px-2 py-1 text-xs font-bold text-white">
175→                            {urgentCount} urgente{urgentCount > 1 ? 's' : ''}
176→                        </span>
177→                    )}
178→                    {warningCount > 0 && (
179→                        <span className="inline-flex items-center gap-1 bg-[#FFF3E0] px-2 py-1 text-xs font-bold text-[#E65100]">
180→                            {warningCount} atención
181→                        </span>
182→                    )}
183→                    {infoCount > 0 && (
184→                        <span className="inline-flex items-center gap-1 bg-[#E3F2FD] px-2 py-1 text-xs font-bold text-[#1565C0]">
185→                            {infoCount} info
186→                        </span>
187→                    )}
188→                </div>
189→
190→                <div className="flex gap-0 border-2 border-black">
191→                    {filters.map((f) => (
192→                        <button
193→                            key={f.key}
194→                            onClick={() => setFilter(f.key)}
195→                            className={`flex-1 py-2 text-xs font-bold ${filter === f.key ? 'bg-black text-white' : 'bg-white text-black'}`}
196→                        >
197→                            {f.label}
198→                        </button>
199→                    ))}
200→                </div>
201→
202→                {filtered.length === 0 ? (
203→                    <div className="flex flex-col items-center gap-3 py-16 text-center">
204→                        <CheckCircle2 className="size-12 text-[#2E7D32]" />
205→                        <p className="text-lg font-bold">Todo al día</p>
206→                        <p className="text-sm text-[#757575]">No tienes alertas pendientes. Te avisaremos cuando haya algo nuevo.</p>
207→                    </div>
208→                ) : (
209→                    <div className="flex flex-col gap-3">
210→                        {filtered.map((regulation) => (
211→                            <AlertCard key={regulation.id} regulation={regulation} />
212→                        ))}
213→                    </div>
214→                )}
215→            </div>
216→        </AppLayout>
217→    );
218→}
